        <label>Amount received<input type="number" name="amount" min="0.01" max="{{ number_format($financial['outstanding'], 2, '.', '') }}" step="0.01" value="{{ number_format($minimumDue, 2, '.', '') }}" required></label>
        <label>Reference (optional)<input name="payment_reference" maxlength="100" placeholder="Receipt or transaction number"></label>
        <label>Staff note (optional)<textarea name="notes" maxlength="500" rows="2" placeholder="Payment details"></textarea></label>
        <button class="status-select confirmed" type="submit">Record payment</button>
