<article class="panel detail-card"><div class="panel-heading"><div><p class="admin-kicker">ACTIVITY</p><h2>History</h2></div></div>@forelse($booking->activityLogs->sortByDesc('created_at') as $log)<p class="booking-note"><b>{{ str_replace('_', ' ', ucfirst($log->event)) }}</b><br>{{ $log->created_at->format('M j, Y g:i A') }} · {{ $log->user?->name ?? 'System' }}</p>@empty<p class="empty-copy">No activity has been recorded yet.</p>@endforelse</article></section></main></div></body></html>
